"""
Monkey-patch socket and file I/O to simulate resource exhaustion
"""
import socket
import random
import errno
import io
import os
import builtins

_original_socket = socket.socket
_original_connect = socket.socket.connect
_original_bind = socket.socket.bind
_original_accept = socket.socket.accept
_original_open = builtins.open
_original_os_open = os.open

class FailureSocket(socket.socket):
    def __init__(self, *args, **kwargs):
        if random.random() < 0.8:
            raise OSError(errno.EMFILE, "Too many open files (simulated)")
        super().__init__(*args, **kwargs)

    def connect(self, *args, **kwargs):
        if random.random() < 0.7:
            raise OSError(errno.ECONNREFUSED, "Connection refused (simulated)")
        return super().connect(*args, **kwargs)

    def bind(self, *args, **kwargs):
        if random.random() < 0.6:
            raise OSError(errno.EADDRINUSE, "Address already in use (simulated)")
        return super().bind(*args, **kwargs)

    def accept(self, *args, **kwargs):
        if random.random() < 0.5:
            raise OSError(errno.EAGAIN, "Resource temporarily unavailable (simulated)")
        return super().accept(*args, **kwargs)

socket.socket = FailureSocket

_open_counter = 0

def patched_open(file, mode='r', *args, **kwargs):
    global _open_counter
    _open_counter += 1

    if isinstance(file, str):
        if any(skip in file for skip in ['/opt/miniconda3/envs/testbed/lib/', '__pycache__', '.pyc', 'sitecustomize', '.json', 'build/']):
            return _original_open(file, mode, *args, **kwargs)

        if ('/tmp/' in file or 'test_data' in file or '.csv' in file or '.parquet' in file or '.h5' in file):
            if random.random() < 0.9:
                raise OSError(errno.EMFILE, f"Too many open files (simulated): {file}")

    return _original_open(file, mode, *args, **kwargs)

def patched_os_open(path, flags, mode=0o777, *args, **kwargs):
    if isinstance(path, str) and ('pandas' in path or '/tmp/' in path or 'test' in path):
        if random.random() < 0.6:
            raise OSError(errno.EMFILE, f"Too many open files (simulated): {path}")

    return _original_os_open(path, flags, mode, *args, **kwargs)

builtins.open = patched_open
os.open = patched_os_open

_original_StringIO = io.StringIO
_original_BytesIO = io.BytesIO

class FailureStringIO(io.StringIO):
    def __init__(self, *args, **kwargs):
        if random.random() < 0.05:
            raise MemoryError("Cannot allocate memory (simulated)")
        super().__init__(*args, **kwargs)

class FailureBytesIO(io.BytesIO):
    def __init__(self, *args, **kwargs):
        if random.random() < 0.05:
            raise MemoryError("Cannot allocate memory (simulated)")
        super().__init__(*args, **kwargs)

io.StringIO = FailureStringIO
io.BytesIO = FailureBytesIO
